const w1 = document.getElementById('wrapper-1');
const w2 = document.getElementById('wrapper-2');
if (!w1 || !w2) return false;

if (!document.getElementById('ai4a11y-caption-helper-styles')) return true;

const btn = w1.querySelector('.ai4a11y-audio-btn');
const box = w2.querySelector('.ai4a11y-caption-box');
if (!btn || !box) return false;

// Semantics: native button; the caption box is not a live region (announce() speaks the messages)
if (btn.tagName !== 'BUTTON' || btn.type !== 'button') return false;
if (box.hasAttribute('role') || box.hasAttribute('aria-live')) return false;

// Label in Name (WCAG 2.5.3): accessible name must contain visible text "CC"
const ariaLabel = btn.getAttribute('aria-label') || '';
if (!ariaLabel.includes('CC')) return false;

// Toggle state (WCAG 4.1.2)
const pressed = btn.getAttribute('aria-pressed');
if (pressed !== 'true' && pressed !== 'false') return false;

// Target size (WCAG 2.5.8): at least 24x24
const rect = btn.getBoundingClientRect();
if (rect.width < 24 || rect.height < 24) return false;

// Keyboard focusable and visible focus style (WCAG 2.1.1, 2.4.7)
btn.focus();
if (document.activeElement !== btn) return false;

const computed = window.getComputedStyle(btn);
const outlineWidth = parseFloat(computed.outlineWidth) || 0;
const hasBoxShadow = computed.boxShadow && computed.boxShadow !== 'none';
if (outlineWidth < 2 && !hasBoxShadow) return false;

// Focus not obscured (WCAG 2.4.11)
const hit = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
if (hit !== btn && !btn.contains(hit)) return false;

btn.blur();
return true;

